// 百度地图坐标多屏店铺采集 v2
// 流程：验证输入 -> 地址解析/坐标标准化 -> 中心半径检索 -> 必要时重叠网格补采 -> UID 去重 -> 有界保存。
const input = tobub.params || {};
const locationInput = String(input.location ?? '').trim();
const keyword = String(input.keyword ?? '店铺').trim();
const region = String(input.region ?? '').trim();
const coordinateType = String(input.coordinateType ?? 'bd09ll').trim().toLowerCase();
const radiusKm = Number(input.radiusKm ?? 2);
const requestedLimit = Number(input.limit ?? 20);
const requestedZoom = Number(input.zoom ?? 18);

if (!locationInput) throw new Error('location is required: enter an address or latitude,longitude.');
if (!keyword || keyword.length > 100) throw new Error('keyword must contain 1 to 100 characters.');
if (region.length > 80) throw new Error('region must contain no more than 80 characters.');
if (!['bd09ll', 'gcj02', 'wgs84'].includes(coordinateType))
  throw new Error('coordinateType must be bd09ll, gcj02, or wgs84.');
if (!Number.isFinite(radiusKm) || radiusKm < 0.2 || radiusKm > 10)
  throw new Error('radiusKm must be between 0.2 and 10.');
if (!Number.isInteger(requestedLimit) || requestedLimit < 1 || requestedLimit > 500)
  throw new Error('limit must be an integer from 1 through 500.');
if (!Number.isInteger(requestedZoom) || requestedZoom < 10 || requestedZoom > 21)
  throw new Error('zoom must be an integer from 10 through 21.');

const MAX_TILES = 120;
const MAX_PAGES_PER_QUERY = 8;
const MAX_CONSECUTIVE_QUERY_FAILURES = 3;
const MAP_TIMEOUT_MS = 60000;
const SEARCH_READY_TIMEOUT_MS = 20000;
const PAGE_CHANGE_TIMEOUT_MS = 10000;
const RADIUS_EDGE_TOLERANCE_KM = 0;
const PI = Math.PI;

function validateLatLng(lat, lng, label) {
  if (!Number.isFinite(lat) || lat < -90 || lat > 90 || !Number.isFinite(lng) || lng < -180 || lng > 180)
    throw new Error(label + ' must contain valid latitude and longitude values.');
  return { lat, lng };
}

function parseCoordinateInput(value) {
  const parts = value.replace(/[，；;]/g, ',').trim().split(/[\s,]+/).filter(Boolean);
  if (parts.length !== 2) return null;
  const lat = Number(parts[0]);
  const lng = Number(parts[1]);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  return validateLatLng(lat, lng, 'Coordinate input');
}

function outsideChina(lat, lng) {
  return lng < 72.004 || lng > 137.8347 || lat < 0.8293 || lat > 55.8271;
}
function transformLatitude(x, y) {
  let value = -100 + 2 * x + 3 * y + 0.2 * y * y + 0.1 * x * y + 0.2 * Math.sqrt(Math.abs(x));
  value += (20 * Math.sin(6 * x * PI) + 20 * Math.sin(2 * x * PI)) * 2 / 3;
  value += (20 * Math.sin(y * PI) + 40 * Math.sin(y / 3 * PI)) * 2 / 3;
  value += (160 * Math.sin(y / 12 * PI) + 320 * Math.sin(y * PI / 30)) * 2 / 3;
  return value;
}
function transformLongitude(x, y) {
  let value = 300 + x + 2 * y + 0.1 * x * x + 0.1 * x * y + 0.1 * Math.sqrt(Math.abs(x));
  value += (20 * Math.sin(6 * x * PI) + 20 * Math.sin(2 * x * PI)) * 2 / 3;
  value += (20 * Math.sin(x * PI) + 40 * Math.sin(x / 3 * PI)) * 2 / 3;
  value += (150 * Math.sin(x / 12 * PI) + 300 * Math.sin(x / 30 * PI)) * 2 / 3;
  return value;
}
function wgs84ToGcj02(point) {
  if (outsideChina(point.lat, point.lng)) return point;
  const a = 6378245;
  const eccentricity = 0.00669342162296594323;
  let dLat = transformLatitude(point.lng - 105, point.lat - 35);
  let dLng = transformLongitude(point.lng - 105, point.lat - 35);
  const radLat = point.lat / 180 * PI;
  let magic = Math.sin(radLat);
  magic = 1 - eccentricity * magic * magic;
  const sqrtMagic = Math.sqrt(magic);
  dLat = dLat * 180 / ((a * (1 - eccentricity)) / (magic * sqrtMagic) * PI);
  dLng = dLng * 180 / (a / sqrtMagic * Math.cos(radLat) * PI);
  return { lat: point.lat + dLat, lng: point.lng + dLng };
}
function gcj02ToBd09(point) {
  const z = Math.sqrt(point.lng * point.lng + point.lat * point.lat) + 0.00002 * Math.sin(point.lat * PI * 3000 / 180);
  const theta = Math.atan2(point.lat, point.lng) + 0.000003 * Math.cos(point.lng * PI * 3000 / 180);
  return { lat: z * Math.sin(theta) + 0.006, lng: z * Math.cos(theta) + 0.0065 };
}
function inputToBd09(point, type) {
  if (type === 'bd09ll') return point;
  return gcj02ToBd09(type === 'wgs84' ? wgs84ToGcj02(point) : point);
}

// 百度地图官方 JS API 使用分带多项式进行 BD09MC/BD09LL 转换。
const MC_BANDS = [12890594.86, 8362377.87, 5591021, 3481989.83, 1678043.12, 0];
const MC2LL = [
  [1.410526172116255e-8, 0.00000898305509648872, -1.9939833816331, 200.9824383106796, -187.2403703815547, 91.6087516669843, -23.38765649603339, 2.57121317296198, -0.03801003308653, 17337981.2],
  [-7.435856389565537e-9, 0.000008983055097726239, -0.78625201886289, 96.32687599759846, -1.85204757529826, -59.36935905485877, 47.40033549296737, -16.50741931063887, 2.28786674699375, 10260144.86],
  [-3.030883460898826e-8, 0.00000898305509983578, 0.30071316287616, 59.74293618442277, 7.35798407487126, -25.38371002664745, 13.45380521110908, -3.29883767235584, 0.32710905363475, 6856817.37],
  [-1.981981304930552e-8, 0.000008983055099779535, 0.03278182852591, 40.31678527705744, 0.65659298677277, -4.44255534477492, 0.85341911805263, 0.12923347998204, -0.04625736007561, 4482777.06],
  [3.09191371068437e-9, 0.000008983055096812155, 0.00006995724062, 23.10934304144901, -0.00023663490511, -0.6321817810242, -0.00663494467273, 0.03430082397953, -0.00466043876332, 2555164.4],
  [2.890871144776878e-9, 0.000008983055095805407, -3.068298e-8, 7.47137025468032, -0.00000353937994, -0.02145144861037, -0.00001234426596, 0.00010322952773, -0.00000323890364, 826088.5],
];
function bd09McToBd09Ll(mapX, mapY) {
  const ax = Math.abs(mapX);
  const ay = Math.abs(mapY);
  let bandIndex = MC_BANDS.findIndex((band) => ay >= band);
  if (bandIndex < 0) bandIndex = MC_BANDS.length - 1;
  const c = MC2LL[bandIndex];
  const ratio = ay / c[9];
  const lng = c[0] + c[1] * ax;
  const lat = c[2] + c[3] * ratio + c[4] * ratio ** 2 + c[5] * ratio ** 3
    + c[6] * ratio ** 4 + c[7] * ratio ** 5 + c[8] * ratio ** 6;
  return { lat: mapY < 0 ? -lat : lat, lng: mapX < 0 ? -lng : lng };
}
function mapCenterFromUrl(url) {
  const match = String(url).match(/@(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?),(\d+(?:\.\d+)?)z(?:[/?#]|$)/);
  let mapX = null;
  let mapY = null;
  let zoom = null;
  if (match) {
    mapX = Number(match[1]);
    mapY = Number(match[2]);
    zoom = Number(match[3]);
  } else {
    try {
      const current = new URL(String(url));
      mapX = Number(current.searchParams.get('nb_x'));
      mapY = Number(current.searchParams.get('nb_y'));
      if (![mapX, mapY].every(Number.isFinite)) {
        const rawCenter = current.searchParams.get('c');
        const centerParts = rawCenter ? rawCenter.split(',').map(Number) : [];
        if (centerParts.length === 2 && centerParts.every(Number.isFinite)) [mapX, mapY] = centerParts;
      }
      zoom = mapZoomFromUrl(url);
    } catch {
      return null;
    }
  }
  const center = bd09McToBd09Ll(mapX, mapY);
  if (![center.lat, center.lng, zoom].every(Number.isFinite)) return null;
  return { ...center, mapX, mapY, zoom };
}
function mapZoomFromUrl(url) {
  try {
    const rawZoom = new URL(String(url)).searchParams.get('l');
    if (rawZoom !== null) {
      const queryZoom = Number(rawZoom);
      if (Number.isFinite(queryZoom) && queryZoom >= 0) return queryZoom;
    }
  } catch {}
  const match = String(url).match(/,(-?\d+(?:\.\d+)?)z(?:[/?#]|$)/);
  return match ? Number(match[1]) : null;
}
function mapCenterFromMapUrl(url) {
  const routeCenter = mapCenterFromUrl(url);
  if (routeCenter) return routeCenter;
  try {
    const current = new URL(String(url));
    let mapX = Number(current.searchParams.get('nb_x'));
    let mapY = Number(current.searchParams.get('nb_y'));
    if (![mapX, mapY].every(Number.isFinite)) {
      const rawCenter = current.searchParams.get('c');
      const centerParts = rawCenter ? rawCenter.split(',').map(Number) : [];
      if (centerParts.length === 2 && centerParts.every(Number.isFinite)) [mapX, mapY] = centerParts;
    }
    if (![mapX, mapY].every(Number.isFinite)) return null;
    const point = bd09McToBd09Ll(mapX, mapY);
    return { ...point, mapX, mapY };
  } catch {
    return null;
  }
}
function buildVisibleMapUrl(sourceUrl) {
  try {
    const pageUrl = new URL(String(sourceUrl));
    let mapX = Number(pageUrl.searchParams.get('nb_x'));
    let mapY = Number(pageUrl.searchParams.get('nb_y'));
    if (![mapX, mapY].every(Number.isFinite)) {
      const routeCenter = mapCenterFromUrl(sourceUrl);
      if (!routeCenter) return null;
      mapX = routeCenter.mapX;
      mapY = routeCenter.mapY;
    }
    const x = Number(mapX.toFixed(6));
    const y = Number(mapY.toFixed(6));
    pageUrl.pathname = '/search/' + encodeURIComponent(keyword) + '/@' + x + ',' + y + ',' + requestedZoom + 'z';
    pageUrl.searchParams.set('querytype', 'nb');
    pageUrl.searchParams.set('wd', keyword);
    pageUrl.searchParams.set('nb_x', String(x));
    pageUrl.searchParams.set('nb_y', String(y));
    return 'https://map.baidu.com/@' + x + ',' + y + ',' + requestedZoom + 'z';
  } catch {
    return null;
  }
}

let center;
let locationMode;
let mapPage = null;
let coveragePage = null;
const visiblePage = await tobub.browser.current();
let addressResolution = null;
const coordinateInput = parseCoordinateInput(locationInput);
if (coordinateInput) {
  center = inputToBd09(coordinateInput, coordinateType);
  locationMode = 'coordinates';
} else {
  locationMode = 'address';
  const geocodeAddress = (region && !locationInput.includes(region) ? region + ' ' : '') + locationInput;
  const geocodeParams = new URLSearchParams({
    address: geocodeAddress,
    output: 'html',
    src: 'webapp.baidu.openAPIdemo',
    coord_type: 'bd09ll',
    // 百度地址 URI 在 zoom=19 时可能退回城市概览；固定用已验证的 18 级解析中心。
    zoom: '18',
  });
  mapPage = await tobub.browser.open({
    url: 'https://api.map.baidu.com/geocoder?' + geocodeParams.toString(),
    waitUntil: 'domcontentloaded',
    timeout: MAP_TIMEOUT_MS,
  });
  await tobub.browser.bringToFront(visiblePage);
  let resolvedState = null;
  let stableAddressUrl = '';
  let stableAddressSamples = 0;
  for (let attempt = 0; attempt < 40; attempt++) {
    const observation = await tobub.atoms.evaluate({
      expression: '() => ({ url: location.href, title: document.title, text: (document.body?.innerText || "").slice(0, 1200), links: Array.from(document.querySelectorAll("a[href]")).map(a => a.href).filter(href => /uid=/.test(href) && /lat=/.test(href) && /lng=/.test(href)).slice(0, 40) })',
    }, { page: mapPage });
    resolvedState = observation.value;
    const currentUrl = new URL(resolvedState.url);
    const currentQuery = currentUrl.searchParams.get('wd') || '';
    const normalizeAddress = (value) => String(value || '').replace(/[\s,，;；\-—（）()]+/g, '').toLowerCase();
    const normalizedInput = normalizeAddress(locationInput);
    const normalizedRegion = normalizeAddress(region);
    const addressCore = normalizedRegion ? normalizedInput.replace(normalizedRegion, '') : normalizedInput;
    const normalizedQuery = normalizeAddress(currentQuery);
    const queryMatches = normalizedQuery.includes(normalizedInput)
      || (addressCore.length >= 2 && normalizedQuery.includes(addressCore));
    const addressPageMatches = currentUrl.hostname === 'map.baidu.com'
      && currentUrl.pathname.startsWith('/search/')
      && queryMatches;
    const addressPins = addressPageMatches ? (resolvedState.links || []).map((href) => {
      try {
        const linkUrl = new URL(href);
        const params = linkUrl.searchParams;
        const mapX = Number(params.get('lng'));
        const mapY = Number(params.get('lat'));
        const name = normalizeAddress(params.get('place') || '');
        const hasUid = Boolean(params.get('uid'));
        if (!hasUid || !name || !Number.isFinite(mapX) || !Number.isFinite(mapY)
          || Math.abs(mapX) < 1000000 || Math.abs(mapY) < 1000000) return null;
        const exactOrContained = addressCore.length >= 2
          && (name.includes(addressCore) || addressCore.includes(name));
        const inputContained = normalizedInput.length >= 2
          && (name.includes(normalizedInput) || normalizedInput.includes(name));
        return { mapX, mapY, name, score: exactOrContained ? 3 : inputContained ? 2 : 0 };
      } catch { return null; }
    }).filter((pin) => pin && pin.score > 0).sort((a, b) => b.score - a.score) : [];
    const matchedPin = addressPins[0] || null;
    const candidateCenter = matchedPin
      ? { ...bd09McToBd09Ll(matchedPin.mapX, matchedPin.mapY), mapX: matchedPin.mapX, mapY: matchedPin.mapY }
      : null;
    // 地址中心采用与搜索词匹配的百度 POI 标记坐标，不使用自动缩放后的视口中心。
    if (candidateCenter) {
      stableAddressSamples = resolvedState.url === stableAddressUrl ? stableAddressSamples + 1 : 0;
      stableAddressUrl = resolvedState.url;
      center = candidateCenter;
    } else {
      stableAddressUrl = '';
      stableAddressSamples = 0;
      center = null;
    }
    if (center && stableAddressSamples >= 2) {
      addressResolution = {
        url: resolvedState.url,
        title: resolvedState.title,
        preview: String(resolvedState.text || '').slice(0, 500),
      };
      break;
    }
    if (resolvedState.url.includes('error.html')) break;
    await tobub.atoms.waitFor({ delay: 300 });
  }
  if (!center)
    throw new Error('Could not resolve a matching Baidu POI coordinate for the address: ' + JSON.stringify(resolvedState));
  center = { lat: center.lat, lng: center.lng };
}
center = validateLatLng(Number(center.lat), Number(center.lng), 'Resolved center');

function distanceKm(a, b) {
  const rad = (degrees) => degrees * PI / 180;
  const dLat = rad(b.lat - a.lat);
  const dLng = rad(b.lng - a.lng);
  const h = Math.sin(dLat / 2) ** 2
    + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 6371.0088 * 2 * Math.atan2(Math.sqrt(h), Math.sqrt(Math.max(0, 1 - h)));
}
function coordinateOffset(origin, eastKm, northKm) {
  const lat = origin.lat + northKm / 111.32;
  const cosine = Math.max(0.2, Math.cos(origin.lat * PI / 180));
  const lng = origin.lng + eastKm / (111.32 * cosine);
  return { lat: Number(lat.toFixed(7)), lng: Number(lng.toFixed(7)) };
}
function buildSearchUrl(searchCenter, radiusMeters) {
  const params = new URLSearchParams({
    query: keyword,
    location: searchCenter.lat.toFixed(7) + ',' + searchCenter.lng.toFixed(7),
    radius: String(Math.round(radiusMeters)),
    output: 'html',
    src: 'webapp.baidu.openAPIdemo',
    coord_type: 'bd09ll',
    zoom: String(requestedZoom),
  });
  if (region) params.set('region', region);
  return 'https://api.map.baidu.com/place/search?' + params.toString();
}

const listExpression = `() => {
  const visible = (element) => {
    const rect = element.getBoundingClientRect();
    const style = getComputedStyle(element);
    return rect.width > 0 && rect.height > 0 && style.display !== 'none' && style.visibility !== 'hidden' && style.opacity !== '0';
  };
  const list = document.querySelector('.poilist');
  const items = Array.from(document.querySelectorAll('.poilist > li.search-item')).filter(visible).map((element) => {
    const title = element.querySelector('a.n-blue');
    const amend = element.querySelector('a.amend[href]');
    let uid = '';
    let mapX = null;
    let mapY = null;
    try {
      const url = amend ? new URL(amend.href) : null;
      uid = url?.searchParams.get('uid') || '';
      mapX = Number(url?.searchParams.get('lng'));
      mapY = Number(url?.searchParams.get('lat'));
    } catch {}
    const addressNode = element.querySelector('.row.addr span[title]') || element.querySelector('.row.addr span');
    const phoneNode = element.querySelector('.row.tel');
    const distanceNode = element.querySelector('.mt_5 .n-grey');
    return {
      uid,
      name: (title?.textContent || '').trim(),
      address: (addressNode?.getAttribute('title') || addressNode?.textContent || '').trim(),
      phone: (phoneNode?.textContent || '').trim().replace(/^电话\\s*[:：]?\\s*/, ''),
      distanceLabel: (distanceNode?.textContent || '').trim(),
      mapX,
      mapY,
    };
  }).filter((item) => item.name);
  const pager = document.querySelector('.poi-page');
  const pageText = pager?.querySelector('.curPage')?.textContent?.trim() || '';
  const currentPage = Number.parseInt(pageText, 10) || 1;
  const nextAnchor = pager?.querySelector('a[tid="toNextPage"]');
  const nextPageTarget = Number(nextAnchor?.getAttribute('onclick')?.match(/toPage\\((\\d+)\\)/)?.[1] || 0);
  const pageNumbers = Array.from(pager?.querySelectorAll('a') || []).map((a) => Number((a.textContent || '').trim())).filter(Number.isInteger);
  const listText = (list?.innerText || '') + ' ' + (document.querySelector('.poi-empty')?.innerText || '');
  const emptySignal = /暂无|没有找到|未找到|未能找到|没有相关|无相关|抱歉|无结果|0条/.test(listText);
  return {
    url: location.href,
    title: document.title,
    currentPage,
    pageNumbers,
    nextPageTarget,
    nextPageAvailable: !!nextAnchor && nextPageTarget > currentPage,
    items,
    emptySignal,
    listExists: !!list,
    listText: listText.slice(0, 500),
  };
}`;
async function readListState(page = mapPage) {
  const result = await tobub.atoms.evaluate({ expression: listExpression }, { page });
  return result.value;
}
async function waitForFirstListState(page = mapPage) {
  const startedAt = Date.now();
  let latest = null;
  let emptySamples = 0;
  while (Date.now() - startedAt < SEARCH_READY_TIMEOUT_MS) {
    latest = await readListState(page);
    if (latest.items.length > 0) return latest;
    emptySamples = latest.emptySignal ? emptySamples + 1 : 0;
    if (latest.listExists && emptySamples >= 2) return latest;
    await tobub.atoms.waitFor({ delay: 300 });
  }
  throw new Error('Baidu result list did not become ready: ' + JSON.stringify(latest));
}
function parseDistanceLabel(value) {
  const match = String(value || '').match(/([\d.]+)\s*(公里|千米|km|米|m)/i);
  if (!match) return null;
  const amount = Number(match[1]);
  if (!Number.isFinite(amount)) return null;
  return /^(公里|千米|km)$/i.test(match[2]) ? amount : amount / 1000;
}
function formatDistanceLabel(distanceKmValue) {
  const meters = Math.round(distanceKmValue * 1000);
  return meters < 1000 ? meters + '米' : (distanceKmValue.toFixed(2) + '公里');
}

const recordsByUid = new Map();
const searches = [];
let candidatesSeen = 0;
let duplicateCount = 0;
let excludedOutsideRadius = 0;
let extractionFailures = 0;
let totalPagesLoaded = 0;
let consecutiveQueryFailures = 0;
let queryRetries = 0;
let tileLimitReached = false;
let pageLimitReached = false;

async function collectSearch(searchCenter, searchRadiusKm, searchKind, tileIndex = 0) {
  const search = {
    index: searches.length + 1,
    kind: searchKind,
    tile_index: tileIndex,
    center: { lat: searchCenter.lat, lng: searchCenter.lng },
    radius_m: Math.round(searchRadiusKm * 1000),
    zoom: requestedZoom,
    pages_loaded: 0,
    results_seen: 0,
    records_added: 0,
    status: 'partial',
    stop_reason: 'query_failed',
    error: null,
    retry_scheduled: false,
    page_url: '',
    actual_map_zoom: null,
    zoom_mismatch: false,
  };
  searches.push(search);
  let targetPage = mapPage;
  try {
    const searchUrl = buildSearchUrl(searchCenter, search.radius_m);
    if (!mapPage) {
      mapPage = await tobub.browser.open({ url: searchUrl, waitUntil: 'domcontentloaded', timeout: MAP_TIMEOUT_MS });
      await tobub.browser.bringToFront(visiblePage);
      targetPage = mapPage;
    } else if (searchKind === 'coverage_tile') {
      if (!coveragePage) {
        coveragePage = await tobub.browser.open({});
        await tobub.browser.bringToFront(visiblePage);
      }
      targetPage = coveragePage;
      await tobub.atoms.navigate(
        { url: searchUrl, waitUntil: 'domcontentloaded' },
        { page: targetPage, timeout: MAP_TIMEOUT_MS },
      );
    } else {
      targetPage = mapPage;
      await tobub.atoms.navigate(
        { url: searchUrl, waitUntil: 'domcontentloaded' },
        { page: targetPage, timeout: MAP_TIMEOUT_MS },
      );
    }
    let state = await waitForFirstListState(targetPage);
    search.page_url = String(state.url || '');
    search.actual_map_zoom = mapZoomFromUrl(state.url);
    search.zoom_mismatch = search.actual_map_zoom !== null && search.actual_map_zoom !== requestedZoom;
    if (!state.items.length && state.emptySignal) {
      search.status = 'empty';
      search.stop_reason = 'no_results';
      consecutiveQueryFailures = 0;
      return search;
    }
    for (let pageAttempt = 0; pageAttempt < MAX_PAGES_PER_QUERY; pageAttempt++) {
      if (pageAttempt > 0) {
        if (!state.nextPageAvailable) {
          search.status = 'complete';
          search.stop_reason = 'no_next_page';
          break;
        }
        const priorPage = state.currentPage;
        const expectedNextPage = state.nextPageTarget || priorPage + 1;
        const activation = await tobub.atoms.evaluate({
          expression: '() => { const anchor = document.querySelector(".poi-page a[tid=toNextPage]"); if (!anchor) return { activated: false }; const onclick = anchor.getAttribute("onclick") || ""; anchor.click(); return { activated: true, onclick }; }',
        }, { page: targetPage });
        if (!activation.value?.activated) {
          search.status = 'complete';
          search.stop_reason = 'no_next_page';
          break;
        }
        const pageWaitStartedAt = Date.now();
        let nextState = state;
        while (Date.now() - pageWaitStartedAt < PAGE_CHANGE_TIMEOUT_MS) {
          await tobub.atoms.waitFor({ delay: 250 });
          nextState = await readListState(targetPage);
          if (nextState.currentPage >= expectedNextPage && nextState.items.length > 0) break;
        }
        if (nextState.currentPage < expectedNextPage || !nextState.items.length) {
          search.status = 'partial';
          search.stop_reason = 'page_cap';
          search.error = 'The Baidu result feed did not advance to the next page.';
          pageLimitReached = true;
          break;
        }
        state = nextState;
      }
      search.pages_loaded++;
      totalPagesLoaded++;
      search.results_seen += state.items.length;
      for (const item of state.items) {
        if (recordsByUid.size >= requestedLimit) {
          search.status = 'complete';
          search.stop_reason = 'limit_reached';
          break;
        }
        if (!item.uid || !Number.isFinite(item.mapX) || !Number.isFinite(item.mapY)) {
          extractionFailures++;
          continue;
        }
        candidatesSeen++;
        const poi = bd09McToBd09Ll(item.mapX, item.mapY);
        const distanceFromOriginKm = distanceKm(center, poi);
        if (distanceFromOriginKm > radiusKm) {
          excludedOutsideRadius++;
          continue;
        }
        if (recordsByUid.has(item.uid)) {
          duplicateCount++;
          const existing = recordsByUid.get(item.uid);
          if (!existing.found_in_queries.includes(search.index)) existing.found_in_queries.push(search.index);
          continue;
        }
        const record = {
          uid: item.uid,
          name: item.name,
          address: item.address,
          phone: item.phone,
          latitude: Number(poi.lat.toFixed(7)),
          longitude: Number(poi.lng.toFixed(7)),
          map_x: item.mapX,
          map_y: item.mapY,
          distance_km: Number(distanceFromOriginKm.toFixed(4)),
          distance_label: formatDistanceLabel(distanceFromOriginKm),
          baidu_distance_label: item.distanceLabel,
          distance_label_center: { lat: center.lat, lng: center.lng },
          detail_url: 'https://api.map.baidu.com/place/detail?' + new URLSearchParams({ uid: item.uid, output: 'html', src: 'webapp.baidu.openAPIdemo' }).toString(),
          found_in_queries: [search.index],
        };
        recordsByUid.set(item.uid, record);
        search.records_added++;
        if (recordsByUid.size >= requestedLimit) {
          search.status = 'complete';
          search.stop_reason = 'limit_reached';
          break;
        }
      }
      if (search.stop_reason === 'limit_reached') break;
      if (!state.nextPageAvailable) {
        search.status = 'complete';
        search.stop_reason = 'no_next_page';
        break;
      }
      if (search.pages_loaded >= MAX_PAGES_PER_QUERY) {
        search.status = 'partial';
        search.stop_reason = 'page_cap';
        pageLimitReached = true;
        break;
      }
    }
    if (recordsByUid.size >= requestedLimit) {
      search.status = 'complete';
      search.stop_reason = 'limit_reached';
    }
    consecutiveQueryFailures = 0;
    return search;
  } catch (error) {
    search.status = 'failed';
    search.stop_reason = 'query_failed';
    search.error = String(error?.message || error || 'Baidu map search failed.').slice(0, 800);
    consecutiveQueryFailures++;
    return search;
  }
}

async function collectSearchWithRetry(searchCenter, searchRadiusKm, searchKind, tileIndex = 0) {
  const firstAttempt = await collectSearch(searchCenter, searchRadiusKm, searchKind, tileIndex);
  if (firstAttempt.status !== 'failed') return firstAttempt;
  const firstError = firstAttempt.error || 'Baidu result list did not become ready.';
  firstAttempt.status = 'partial';
  firstAttempt.retry_scheduled = true;
  firstAttempt.error = ('Retrying once after transient failure: ' + firstError).slice(0, 800);
  queryRetries++;
  await tobub.atoms.waitFor({ delay: 500 });
  return await collectSearch(searchCenter, searchRadiusKm, searchKind, tileIndex);
}

const centerSearch = await collectSearchWithRetry(center, radiusKm, 'center');
let tileRadiusKm = Math.min(1.5, Math.max(0.5, radiusKm));
let tileStepKm = tileRadiusKm * 1.25;
let plannedTiles = [];
let tilesOmittedByCap = 0;
if (recordsByUid.size < requestedLimit && centerSearch.status !== 'failed') {
  const spanKm = radiusKm + tileRadiusKm;
  const steps = Math.ceil(spanKm / tileStepKm);
  for (let row = -steps; row <= steps; row++) {
    for (let column = -steps; column <= steps; column++) {
      const eastKm = column * tileStepKm;
      const northKm = row * tileStepKm;
      const fromCenterKm = Math.hypot(eastKm, northKm);
      if (fromCenterKm < tileStepKm * 0.25 || fromCenterKm > spanKm) continue;
      plannedTiles.push({
        center: coordinateOffset(center, eastKm, northKm),
        distance_from_center_km: Number(fromCenterKm.toFixed(4)),
        east_km: Number(eastKm.toFixed(4)),
        north_km: Number(northKm.toFixed(4)),
      });
    }
  }
  plannedTiles.sort((a, b) => a.distance_from_center_km - b.distance_from_center_km
    || a.north_km - b.north_km || a.east_km - b.east_km);
  if (plannedTiles.length > MAX_TILES) {
    tilesOmittedByCap = plannedTiles.length - MAX_TILES;
    plannedTiles = plannedTiles.slice(0, MAX_TILES);
    tileLimitReached = true;
  }
  for (let index = 0; index < plannedTiles.length; index++) {
    if (recordsByUid.size >= requestedLimit) break;
    if (consecutiveQueryFailures >= MAX_CONSECUTIVE_QUERY_FAILURES) {
      tileLimitReached = true;
      break;
    }
    await collectSearchWithRetry(plannedTiles[index].center, tileRadiusKm, 'coverage_tile', index + 1);
  }
}

let coveragePageClosed = false;
let coveragePageCloseError = null;
let sourceMapUrl = '';
if (mapPage) {
  try {
    const sourceView = await tobub.atoms.evaluate({ expression: '() => ({ url: location.href })' }, { page: mapPage });
    sourceMapUrl = String(sourceView.value?.url || '');
  } catch {}
}
const visibleMapTargetUrl = sourceMapUrl ? buildVisibleMapUrl(sourceMapUrl) : null;
for (const pageToClose of [coveragePage, mapPage]) {
  if (!pageToClose) continue;
  try {
    await tobub.browser.close(pageToClose);
  } catch (error) {
    coveragePageCloseError = String(error?.message || error || 'A temporary query tab could not be closed.').slice(0, 500);
  }
}
coveragePage = null;
mapPage = null;
coveragePageClosed = !coveragePageCloseError;
let visibleMapUrl = '';
let visibleMapZoom = null;
let visibleMapCenter = null;
let visibleMapCenterDistanceKm = null;
let visibleMapVerified = false;
let visibleMapRestoreError = null;
if (visibleMapTargetUrl) {
  try {
    await tobub.browser.bringToFront(visiblePage);
    await tobub.atoms.navigate(
      { url: visibleMapTargetUrl, waitUntil: 'domcontentloaded' },
      { page: visiblePage, timeout: MAP_TIMEOUT_MS },
    );
    let lastObservedUrl = '';
    let stableMatches = 0;
    for (let attempt = 0; attempt < 24; attempt++) {
      const mapView = await tobub.atoms.evaluate({ expression: '() => ({ url: location.href })' }, { page: visiblePage });
      visibleMapUrl = String(mapView.value?.url || '');
      visibleMapZoom = mapZoomFromUrl(visibleMapUrl);
      const currentCenter = mapCenterFromMapUrl(visibleMapUrl);
      visibleMapCenter = currentCenter ? { lat: Number(currentCenter.lat.toFixed(7)), lng: Number(currentCenter.lng.toFixed(7)) } : null;
      const currentCenterDistanceKm = currentCenter ? distanceKm(center, currentCenter) : null;
      visibleMapCenterDistanceKm = currentCenterDistanceKm === null ? null : Number(currentCenterDistanceKm.toFixed(4));
      const matchesRequestedView = visibleMapZoom === requestedZoom && currentCenterDistanceKm !== null && currentCenterDistanceKm <= 0.1;
      stableMatches = matchesRequestedView && visibleMapUrl === lastObservedUrl ? stableMatches + 1 : (matchesRequestedView ? 1 : 0);
      lastObservedUrl = visibleMapUrl;
      if (stableMatches >= 2) { visibleMapVerified = true; break; }
      await tobub.atoms.waitFor({ delay: 250 });
    }
    if (!visibleMapVerified) visibleMapRestoreError = 'Baidu did not keep the requested center and zoom after loading.';
  } catch (error) {
    visibleMapRestoreError = String(error?.message || error || 'Could not open or verify the requested map view.').slice(0, 500);
  }
} else {
  visibleMapRestoreError = 'Baidu did not return coordinates needed to restore the map view.';
}

const records = Array.from(recordsByUid.values())
  .sort((a, b) => a.distance_km - b.distance_km || a.name.localeCompare(b.name, 'zh-CN'))
  .slice(0, requestedLimit);
const requestedCountMet = records.length >= requestedLimit;
const queryFailures = searches.filter((search) => search.status === 'failed').length;
const partialSearchCount = searches.filter((search) => search.status === 'partial' && !search.retry_scheduled).length;
const searchRedirectZoomMismatchCount = searches.filter((search) => search.zoom_mismatch).length;
const zoomMismatchCount = visibleMapZoom === requestedZoom ? 0 : 1;
const searchUrls = searches.map((search) => buildSearchUrl(search.center, search.radius_m));
let collection = null;
let collectionSaveError = null;
let collectionPersisted = records.length === 0;
if (records.length > 0) {
  try {
    collection = await tobub.data.save(records.map((record) => ({
      type: 'baidu-map-store',
      id: record.uid,
      payload: record,
      meta: {
        location_input: locationInput,
        location_mode: locationMode,
        resolved_center: center,
        coordinate_type: 'bd09ll',
        keyword,
        radius_km: radiusKm,
        zoom: requestedZoom,
      },
    })), {
      name: 'baidu-map-stores-v2',
      mode: 'event',
      outputs: [{ type: 'file', format: 'jsonl' }],
      policy: { maxRecords: requestedLimit, maxBytes: 12000000, retentionDays: 30 },
    });
    collectionPersisted = collection?.status === 'completed'
      && collection?.recordCount === records.length && collection?.droppedCount === 0;
  } catch (error) {
    collectionSaveError = String(error?.message || error || 'Collection save failed.').slice(0, 800);
    collectionPersisted = false;
  }
}

let contentItemsSaved = 0;
let contentSaveFailures = 0;
let contentSaveError = null;
let contentPersisted = records.length === 0;
if (records.length > 0) {
  const saveErrors = [];
  const CONTENT_SAVE_BATCH_SIZE = 20;
  for (let offset = 0; offset < records.length; offset += CONTENT_SAVE_BATCH_SIZE) {
    const batch = records.slice(offset, offset + CONTENT_SAVE_BATCH_SIZE);
    const settled = await Promise.allSettled(batch.map((record) => tobub.db.saveContent({
      platform: 'baidu',
      contentType: 'store',
      externalId: record.uid,
      title: record.name || '百度地图店铺',
      summary: record.address || '',
      url: record.detail_url || '',
      rawData: record,
      tags: ['百度地图', '店铺', keyword],
      observationSource: 'baidu-map-store-collector',
      observationMeta: {
        uid: record.uid,
        keyword,
        radiusKm,
        distanceKm: record.distance_km,
        collectionId: collection?.id || null,
      },
      metadata: {
        source: 'baidu-map-store-collector-v2.6',
        locationInput,
        locationMode,
        resolvedCenter: center,
        coordinateType: 'bd09ll',
        keyword,
        region,
        radiusKm,
        zoom: requestedZoom,
        distanceKm: record.distance_km,
        tobub_data: {
          collection_id: collection?.id || null,
          role: 'detail',
          mode: 'event',
          format: 'jsonl',
          schema_version: 1,
        },
      },
    })));
    for (const result of settled) {
      if (result.status === 'fulfilled') {
        contentItemsSaved++;
      } else {
        contentSaveFailures++;
        if (saveErrors.length < 5) saveErrors.push(String(result.reason?.message || result.reason || 'Content save failed.'));
      }
    }
  }
  contentPersisted = contentItemsSaved === records.length && contentSaveFailures === 0;
  if (!contentPersisted) contentSaveError = saveErrors.join(' | ').slice(0, 800) || 'Some content records were not persisted.';
}

let stopReason;
if (requestedCountMet) stopReason = 'limit_reached';
else if (queryFailures > 0 || consecutiveQueryFailures >= MAX_CONSECUTIVE_QUERY_FAILURES) stopReason = 'query_failed';
else if (tileLimitReached) stopReason = 'tile_cap';
else if (pageLimitReached) stopReason = 'page_cap';
else if (extractionFailures > 0) stopReason = 'extraction_failed';
else if (records.length === 0) stopReason = 'no_results';
else stopReason = 'max_radius_reached';
const status = records.length === 0 && queryFailures === 0 && extractionFailures === 0 && stopReason === 'no_results'
  ? 'empty'
  : requestedCountMet && queryFailures === 0 && extractionFailures === 0 && collectionPersisted && contentPersisted
    && zoomMismatchCount === 0 && coveragePageClosed && !coveragePageCloseError
    ? (partialSearchCount === 0 ? 'ok' : 'partial')
    : 'partial';
let statusNote = requestedCountMet
  ? 'Requested count reached; all saved POIs passed the strict distance check from the input center.'
  : 'Requested count was not reached within the selected radius.';
if (partialSearchCount > 0) statusNote += ' At least one Baidu results page did not advance, so search coverage may be incomplete.';
if (zoomMismatchCount > 0) statusNote += ' The visible map zoom differs from the requested zoom.';
if (searchRedirectZoomMismatchCount > 0 && visibleMapVerified) statusNote += ' Search result pages use Baidu’s own zoom; the final visible map was opened at the requested level.';
if (!coveragePageClosed) statusNote += ' The temporary coverage tab could not be closed: ' + (coveragePageCloseError || 'unknown error');
if (visibleMapZoom !== null && visibleMapZoom !== requestedZoom) statusNote += ' The visible map finished at zoom ' + visibleMapZoom + ' instead of ' + requestedZoom + '.';
const summary = {
  status,
  location_input: locationInput,
  location_mode: locationMode,
  resolved_center: { lat: Number(center.lat.toFixed(7)), lng: Number(center.lng.toFixed(7)), coordinate_type: 'bd09ll' },
  location_resolution: addressResolution,
  keyword,
  region,
  radius_km: radiusKm,
  requested_limit: requestedLimit,
  requested_count_met: requestedCountMet,
  zoom: requestedZoom,
  collected: records.length,
  candidates_seen: candidatesSeen,
  duplicate_count: duplicateCount,
  excluded_outside_radius: excludedOutsideRadius,
  extraction_failures: extractionFailures,
  total_pages_loaded: totalPagesLoaded,
  center_search_pages: centerSearch.pages_loaded,
  tile_search_count: searches.filter((search) => search.kind === 'coverage_tile').length,
  planned_tile_count: plannedTiles.length,
  omitted_tile_count: tilesOmittedByCap,
  tile_radius_km: Number(tileRadiusKm.toFixed(3)),
  tile_step_km: Number(tileStepKm.toFixed(3)),
  max_tiles: MAX_TILES,
  max_pages_per_query: MAX_PAGES_PER_QUERY,
  query_failures: queryFailures,
  query_retries: queryRetries,
  partial_search_count: partialSearchCount,
  zoom_mismatch_count: zoomMismatchCount,
  search_redirect_zoom_mismatch_count: searchRedirectZoomMismatchCount,
  visible_map_url: visibleMapUrl,
  visible_map_zoom: visibleMapZoom,
  visible_map_center: visibleMapCenter,
  visible_map_center_distance_km: visibleMapCenterDistanceKm,
  visible_map_verified: visibleMapVerified,
  visible_map_restore_error: visibleMapRestoreError,
  maximum_distance_km: records.length ? Math.max(...records.map((record) => record.distance_km)) : null,
  coverage_page_closed: coveragePageClosed,
  coverage_page_close_error: coveragePageCloseError,
  status_note: statusNote,
  stop_reason: stopReason,
  collection_persisted: collectionPersisted,
  collection_save_error: collectionSaveError,
  content_items_saved: contentItemsSaved,
  content_persisted: contentPersisted,
  content_save_failures: contentSaveFailures,
  content_save_error: contentSaveError,
  collection,
  search_url: searchUrls[0] || '',
  searches,
  coverage_note: "Uses Baidu nearby POI search with the requested center and radius. If center results do not meet the target count, overlapping centers are searched in a temporary tab while the visible map stays at the input center and requested zoom. Every saved POI passes a strict distance check from the original center; distance_label is recalculated from that center, while baidu_distance_label preserves Baidu’s per-query label that may refer to a tile center. Results are deduplicated by UID. Rankings and page limits do not prove all indexed businesses were returned; POI coordinates and computed distances are approximate to Baidu’s precision.",
  radius_edge_tolerance_km: RADIUS_EDGE_TOLERANCE_KM,
};
return { ...summary, records };
